import numpy as np
from pydantic import BaseModel, Field, field_validator


class SalesInput(BaseModel):
    animals: List[str] = Field(..., description="List of animal types available for sale")
    mu: float = Field(..., description="Mean of the Poisson distribution for number of customers")
    seed: Optional[int] = Field(None, description="Optional RNG seed for reproducibility")

