            raise ValueError("animals list must not be empty")
        cleaned = [str(item) for item in v]
        return cleaned

    @field_validator("mu")
    @classmethod
    def validate_mu(cls, v: float) -> float:
        v = float(v)
        if v < 0 or np.isnan(v):
            raise ValueError("mu must be a non-negative number")
        return v


def simulate_pet_shop_sales(animals: List[str], mu: float, seed: Optional[int] = None) -> Dict:
    """
    Simulate pet shop sales.
    - Number of customers ~ Poisson(mu)
    - Each customer buys exactly one animal chosen uniformly at random from `animals`

    Prints a summary and returns a dict:
