            raise ValueError("quantity_sold cannot be negative")
        return v


def _format_money(amount: Decimal, currency: Optional[str] = "USD") -> str:
    # Format with two decimal places, using rounding half-up
    q = amount.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
    # If currency looks like symbol ($, €, etc.), place before; otherwise use code after amount
    if currency in {"$", "€", "£", "¥", "₹"}:
        return f"{currency}{q}"
    else:
        return f"{q} {currency}"


def create_sales_report(products: List[Dict[str, Any]], currency: Optional[str] = "USD") -> List[Dict[str, Any]]:
    """
