      - category
      - quantity_sold (int)
      - revenue_per_item (Decimal)
      - total_revenue (Decimal)
      - revenue_per_item_formatted (str)
      - total_revenue_formatted (str)

    Example:
      create_sales_report([{"name":"Widget","category":"Gadgets","unit_price":"9.99","quantity_sold":10}])
    """
    report: List[Dict[str, Any]] = []

    for p in products:
        prod = Product.model_validate(p)  # pydantic v2 validate
        unit_price = prod.unit_price.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        qty = int(prod.quantity_sold)
        total = (unit_price * Decimal(qty)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)

        item = {
