Note: this function imports its dependencies inside the function so it can be dropped into a script/module easily. Make sure you have pydantic (>=2.0) and requests installed.

```python
def fetch_and_normalize_github_user(username: str) -> dict:
    """
    Retrieve GitHub user data for `username`, normalize all string data to ASCII,
    and return the normalized dictionary.

    Uses pydantic (v2+) to validate the returned JSON. All string values and
    string dictionary keys are normalized via Unicode NFKD decomposition and
    ASCII transliteration (non-ASCII characters removed).

    Raises:
        ValueError: if the user is not found or the GitHub API returns an error.

    Example:
        normalized = fetch_and_normalize_github_user("torvalds")
        print(normalized["name"])  # ASCII-only string or None

    Requirements:
        pip install pydantic requests
    """
    import requests
    import unicodedata
    from pydantic import BaseModel

    # Accept any fields returned by the GitHub API
    class GitHubUser(BaseModel):
        model_config = {"extra": "allow"}

    def normalize_string(s: str) -> str:
        # Use NFKD to decompose combined characters, then drop non-ASCII.
        if s is None:
            return s
        normalized = unicodedata.normalize("NFKD", s)
        ascii_bytes = normalized.encode("ascii", "ignore")
        return ascii_bytes.decode("ascii").strip()

    def normalize_value(value):
        # Recursively normalize strings in data structures.
        if isinstance(value, str):
            return normalize_string(value)
        if isinstance(value, dict):
            out = {}
            for k, v in value.items():
                # Normalize keys if they are strings
                new_key = normalize_string(k) if isinstance(k, str) else k

                # If normalization causes duplicate keys, append a numeric suffix to avoid clobbering
                if new_key in out:
                    base = new_key
                    i = 1
                    while new_key in out:
                        new_key = f"{base}_{i}"
                        i += 1

                out[new_key] = normalize_value(v)
            return out
        if isinstance(value, list):
            return [normalize_value(item) for item in value]
        if isinstance(value, tuple):
            return tuple(normalize_value(item) for item in value)
        # Leave other types (int, bool, None, etc.) unchanged
        return value

    # Fetch from GitHub API
    url = f"https://api.github.com/users/{username}"
    headers = {"Accept": "application/vnd.github+json", "User-Agent": "fetch-and-normalize-script"}
    resp = requests.get(url, headers=headers, timeout=10)

    if resp.status_code == 404:
        raise ValueError(f"GitHub user '{username}' not found (404).")
    if not resp.ok:
        # Provide a concise error message including status and any API text
        raise ValueError(f"GitHub API error {resp.status_code}: {resp.text}")

    try:
        data = resp.json()
    except ValueError as e:
        raise ValueError(f"Failed to parse JSON response: {e}")

    # Validate/accept the data using pydantic (will permit extra fields)
    user = GitHubUser.model_validate(data)
    validated = user.model_dump()

    # Normalize and return
    return normalize_value(validated)
