```python
def summarize_xyz(d):
    """
    Summarize numeric columns 'x', 'y', 'z' from a list of dicts `d`.

    Returns a dict:
      {
        "x": {"mean": ..., "sum": ..., "max": ..., "min": ..., "std": ...},
        "y": {...},
        "z": {...}
      }

    If `d` is empty or a column contains no numeric values, that metric will be None.
    Requires polars (pip install polars).
    """
    try:
        import polars as pl
    except Exception as e:
        raise ImportError("polars is required. Install with: pip install polars") from e

    cols = ["x", "y", "z"]

    # If input is empty, return None metrics for each column
    if not d:
        return {c: {"mean": None, "sum": None, "max": None, "min": None, "std": None} for c in cols}

    # Build a DataFrame; missing keys will become nulls
    df = pl.DataFrame(d)

    # Ensure the three columns exist (create as nulls if missing), and cast to Float64
    for c in cols:
        if c not in df.columns:
            df = df.with_columns(pl.lit(None).alias(c))
    df = df.with_columns([pl.col(c).cast(pl.Float64) for c in cols])

    # Prepare aggregations
    aggs = []
    for c in cols:
        aggs += [
            pl.col(c).mean().alias(f"{c}_mean"),
            pl.col(c).sum().alias(f"{c}_sum"),
            pl.col(c).max().alias(f"{c}_max"),
            pl.col(c).min().alias(f"{c}_min"),
            pl.col(c).std().alias(f"{c}_std"),
        ]

    agg_row = df.select(aggs).to_dicts()[0]

    # Format into nested dict and convert polars types to plain python floats/None
    out = {}
    for c in cols:
        def _py(v):
            # polars may return numpy types or floats; keep None as None
            return None if v is None else float(v)
        out[c] = {
            "mean": _py(agg_row[f"{c}_mean"]),
            "sum": _py(agg_row[f"{c}_sum"]),
            "max": _py(agg_row[f"{c}_max"]),
            "min": _py(agg_row[f"{c}_min"]),
            "std": _py(agg_row[f"{c}_std"]),
        }
    return out

# Example:
