def count_xyz(d):
    """
    Count occurrences of values under keys 'x', 'y', and 'z' in a list of dictionaries `d`.
    Uses pydantic to validate each item is a mapping with optional x/y/z fields.
    Returns: {'x': {value: count, ...}, 'y': {...}, 'z': {...}}

    Unhashable values (lists/dicts) are counted by their repr().
    """
    from pydantic import BaseModel
    from typing import Any, Optional
    from collections import Counter

    class Item(BaseModel):
        x: Optional[Any] = None
        y: Optional[Any] = None
        z: Optional[Any] = None

        class Config:
            extra = "allow"  # allow other keys in the dict

    if not isinstance(d, list):
        raise TypeError("d must be a list of dicts")

    # Validate and coerce each entry
    items = []
    for idx, entry in enumerate(d):
        if not isinstance(entry, dict):
            raise TypeError(f"element {idx} is not a dict")
        items.append(Item(**entry))

    counters = {"x": Counter(), "y": Counter(), "z": Counter()}

    for it in items:
        for key in ("x", "y", "z"):
            val = getattr(it, key)
            if val is None:
                continue
            try:
                counters[key][val] += 1
            except TypeError:
                # unhashable (e.g., list/dict) — fall back to repr
                counters[key][repr(val)] += 1

    return {k: dict(v) for k, v in counters.items()}

