from datetime import datetime, timezone, timedelta
from typing import Union

def elapsed_seconds_including_leap(start: Union[datetime, str]) -> int:
    """
    Return the total number of elapsed seconds from `start` until the current UTC time,
    including any leap seconds that occurred in that interval.

    Parameters:
    - start: datetime (aware or naive) or ISO-8601 string. Naive datetimes are assumed to be UTC.
             ISO strings with 'Z' (e.g. '2020-01-01T12:00:00Z') are supported.

    Returns:
    - int: total elapsed seconds including leap seconds. May be negative if start is in the future.

    Behavior:
    - If start <= now: counts leap seconds L with start < L <= now and adds them to the elapsed seconds.
    - If start > now (start in the future): counts leap seconds between now and start and subtracts them
      (so the returned value is negative and consistently includes leap-second corrections).

    Notes:
    - Attempts to use the 'leapseconds' package if available to fetch a current list of leap-second dates.
      If not available (or if its API is unexpected), falls back to a local table of official leap-second dates
      (through 2016). If you need very recent leap-second data, install/upgrade the 'leapseconds' package
      from PyPI (or provide your own list).
    """
    # Helper: ensure we have an aware UTC datetime
    def _to_utc_dt(obj: Union[datetime, str]) -> datetime:
        if isinstance(obj, datetime):
            dt = obj
            if dt.tzinfo is None:
                # assume UTC for naive datetimes
                return dt.replace(tzinfo=timezone.utc)
            return dt.astimezone(timezone.utc)
        if isinstance(obj, str):
            s = obj.strip()
            # handle trailing 'Z' for UTC
            if s.endswith('Z'):
                s = s[:-1] + '+00:00'
            # Let fromisoformat handle offsets like "+00:00"
            try:
                dt = datetime.fromisoformat(s)
            except Exception:
                # fallback common formats
                fmt_try = ("%Y-%m-%dT%H:%M:%S%z", "%Y-%m-%d %H:%M:%S%z", "%Y-%m-%d")
                for fmt in fmt_try:
                    try:
                        dt = datetime.strptime(s, fmt)
                        break
                    except Exception:
                        dt = None
                if dt is None:
                    raise ValueError(f"Unrecognized datetime string: {obj!r}")
            if dt.tzinfo is None:
                return dt.replace(tzinfo=timezone.utc)
            return dt.astimezone(timezone.utc)
        raise TypeError("start must be a datetime or ISO-8601 string")

    start_dt = _to_utc_dt(start)
    now = datetime.now(timezone.utc)

    # Try to obtain a table of leap-second effective instants (UTC datetimes).
    leap_instants = None

    # Preferred: try using the 'leapseconds' package if present.
    try:
        import leapseconds as _ls  # type: ignore
        # Try common names that packages expose
        candidate = None
        for name in ("get_leap_seconds", "get_table", "leap_seconds", "LEAP_SECONDS", "LEAPSECOND_DATES", "TABLE"):
            if hasattr(_ls, name):
                candidate = getattr(_ls, name)
                break
        if callable(candidate):
            raw = candidate()
        else:
            raw = candidate
        # Normalize raw into list of date strings or datetimes
        if raw is None:
            leap_instants = None
        else:
            instants = []
            # If raw is a dict/sequence of pairs, try to extract keys that look like dates
            if isinstance(raw, dict):
                raw_iter = raw.keys()
            else:
                raw_iter = raw
            for item in raw_iter:
                # item may be a datetime, date, ISO string, or tuple (date, offset)
                if isinstance(item, datetime):
                    dt = item.astimezone(timezone.utc)
                    # represent the leap-second instant as the moment immediately after the inserted second:
                    # for a leap on YYYY-MM-DD, use (YYYY-MM-DD + 1 day) at 00:00:00 UTC
                    instants.append(dt.replace(tzinfo=timezone.utc))
                else:
                    # Try string forms like '1972-06-30' or '1972-06-30T23:59:60Z'
                    s = str(item)
                    s = s.strip()
                    if s.endswith("23:59:60Z") or s.endswith("23:59:60"):
                        # convert '...23:59:60' to next-day midnight
                        try:
                            base = s.split("T")[0]
                            day_dt = datetime.fromisoformat(base).date()
                            instants.append(datetime.combine(day_dt + timedelta(days=1), datetime.min.time(), tzinfo=timezone.utc))
                        except Exception:
                            continue
                    else:
                        # Try to parse as ISO date or datetime
                        try:
                            if s.endswith("Z"):
                                s2 = s[:-1] + "+00:00"
                                dt = datetime.fromisoformat(s2)
                                instants.append(dt.astimezone(timezone.utc))
                            else:
                                # date-only strings -> treat as date of the leap (end of that day)
                                if len(s) == 10 and s[4] == '-' and s[7] == '-':
                                    d = datetime.strptime(s, "%Y-%m-%d").date()
                                    instants.append(datetime.combine(d + timedelta(days=1), datetime.min.time(), tzinfo=timezone.utc))
                                else:
                                    dt = datetime.fromisoformat(s)
                                    if dt.tzinfo is None:
                                        dt = dt.replace(tzinfo=timezone.utc)
                                    instants.append(dt.astimezone(timezone.utc))
                        except Exception:
                            # ignore unparseable items
                            continue
            if instants:
                # dedupe & sort
                instants = sorted({i for i in instants})
                leap_instants = instants
    except Exception:
        leap_instants = None

    # Fallback: built-in official leap-second dates (date on which a leap second was inserted at end of that date).
    # Represented as the instant right after the inserted second: (date + 1 day) 00:00:00 UTC.
    if leap_instants is None:
        # Official leap-second dates (end-of-day dates where a positive leap second was inserted),
        # through 2016 (the last leap second so far).
        _leap_dates = [
            "1972-06-30", "1972-12-31", "1973-06-30", "1973-12-31", "1974-12-31",
            "1975-12-31", "1976-12-31", "1977-12-31", "1978-12-31", "1979-12-31",
            "1981-06-30", "1982-06-30", "1983-06-30", "1985-06-30", "1987-12-31",
            "1989-12-31", "1990-12-31", "1992-06-30", "1993-06-30", "1994-06-30",
            "1995-12-31", "1997-06-30", "1998-12-31", "2005-12-31", "2008-12-31",
            "2012-06-30", "2015-06-30", "2016-12-31",
        ]
        instants = []
        for dstr in _leap_dates:
            d = datetime.strptime(dstr, "%Y-%m-%d").date()
            instants.append(datetime.combine(d + timedelta(days=1), datetime.min.time(), tzinfo=timezone.utc))
        leap_instants = instants

    # Count leap seconds between start and now.
    if start_dt <= now:
        leaps_count = sum(1 for L in leap_instants if start_dt < L <= now)
    else:
        # start in future: subtract leaps that occur between now and start
        leaps_count = -sum(1 for L in leap_instants if now < L <= start_dt)

    elapsed = (now - start_dt).total_seconds() + leaps_count
    # Return integer number of seconds including leap seconds (round toward zero)
    return int(elapsed)
